import json
M=lambda t,sc,pr,cu,tg,en,cd: dict(tier='tier1',level='B2',title='Communicative Challenge: '+t,scenario=sc,prompt=pr,cues=cu,target=tg,english=en,canDo=cd)
P='b2-colombiaperiferias'
c={}
c[P+'-01']=M('Who Founded Cartagena','You are Meg. You and Carlos are watching a documentary about Cartagena, and he asks what the narrator said about the city.','Tell Carlos who founded Cartagena and when.',['Say that the city was founded','Say by whom and in which year'],'Cartagena fue fundada en 1533 por Pedro de Heredia.','Cartagena was founded in 1533 by Pedro de Heredia.',"I can say who founded or built something with *ser* + past participle.")
c[P+'-02']=M('Why So Few Roads','You are Carlos. You have read an article about the Pacific coast of Colombia, and Meg asks how people travel there.','Tell Meg why there are few roads on the Pacific coast.',['Give the reason with a formal connector','Say that there are few roads'],'Debido a la lluvia y a la selva, hay pocas carreteras en el Pacífico.','Because of the rain and the forest, there are few roads on the Pacific coast.',"I can give a cause with *debido a* or *a raíz de* followed by a noun.")
c[P+'-03']=M('A Rule for Collective Lands','You are Meg. You are telling Carlos what you read about Law 70 of 1993 for a talk you are planning.','Say what the law says about the collective lands, in the formal register of a law.',['Say that the lands cannot be sold','Use a formal future form'],'Las tierras colectivas no podrán venderse.','The collective lands may not be sold.',"I can turn an everyday request into a formal rule with *todo aquel que*, the future and *se*.")
c[P+'-04']=M('What the Commission Said','You are Meg. You and Carlos are watching a news report about the Truth Commission, and he asks what it said about the conflict.','Tell Carlos what the Commission said in its 2022 report.',['Say who said it','Say what the conflict had left behind'],'La Comisión dijo en su informe que el conflicto había dejado cientos de miles de muertos.','The Commission said in its report that the conflict had left hundreds of thousands dead.',"I can report what someone said with *dijo que* and the right tense shift.")
c[P+'-05']=M('A Park Closed to Tourists','You are Carlos. You have read an article about Chiribiquete, and Meg asks whether tourists can visit the park.','Tell Meg that the park is closed, and that people still know its paintings.',['Say that the park is closed to tourists','Say that many people still know the paintings'],'Aun cuando el parque está cerrado a los turistas, muchas personas conocen sus pinturas.','Even though the park is closed to tourists, many people know its paintings.',"I can use *aun cuando* with the subjunctive for a possibility and with the indicative for a fact.")
c[P+'-consolidation']=M('Palenque and UNESCO','You are Meg. You are telling Carlos what you remember from your reading about Colombia.','Say what UNESCO did for Palenque in 2005.',['Say who recognised Palenque','Say the year'],'Palenque fue reconocido por la UNESCO en 2005.','Palenque was recognised by UNESCO in 2005.',"I can say who founded, built or recognised something with *ser* + past participle.")
json.dump(c,open('/home/user/parlour-read-b/challenges-colombia-caribbean-pacific.json','w'),indent=2,ensure_ascii=False)
